// ═══════════════════════════════════════════════════════════
// NODE 01 — EXTRACT ALL DATA FROM INCOMING MESSAGE
// ═══════════════════════════════════════════════════════════
const msg  = $json.message || {};
const from = msg.from  || {};
const chat = msg.chat  || {};
const text = (msg.text || '').trim();
const lower = text.toLowerCase();

// Identity
const userId    = String(from.id   || '');
const chatId    = String(chat.id   || '');
const firstName = (from.first_name || '').trim();
const lastName  = (from.last_name  || '').trim();
const fullName  = [firstName, lastName].filter(Boolean).join(' ') || 'Unknown';
const username  = from.username ? '@' + from.username : 'No username';

// Timestamp IST
const now = new Date();
const IST = new Intl.DateTimeFormat('en-IN', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
  hour12: true
});
const dateTime = IST.format(now);

// ─── ROUTING FLAGS ────────────────────────────────────────

// /start command
const isStart = lower === '/start';

// ALL COURSES FALLBACK — student asking for full list
// triggers when AI gave wrong link or student wants everything
const isAllCourses = !isStart && [
  'all courses', 'all course', 'sab courses', 'sab links',
  'wrong link', 'nahi yeh wala', 'galat link', 'other course',
  'show all', 'full list', 'sabhi courses', 'baaki courses',
  'complete list', 'poori list'
].some(k => lower.includes(k));

// BOOKS / MATERIAL — kept as keyword for speed
const isBook = !isStart && !isAllCourses && [
  'book', 'books', 'material', 'notes', 'pdf',
  'study material', 'kota module', 'pyq', 'previous year'
].some(k => lower.includes(k));

// TEST SERIES — kept as keyword for speed
const isTest = !isStart && !isAllCourses && !isBook && [
  'test', 'tests', 'mock', 'series', 'practice',
  'quiz', 'free test', 'test series'
].some(k => lower.includes(k));

// COURSE QUERY — now goes to AI for smart recommendation
// instead of dumping all links
const isCourseQuery = !isStart && !isAllCourses && !isBook && !isTest && [
  'course', 'courses', 'batch', 'join', 'admission',
  'enroll', 'enrolment', 'live class', 'recorded',
  'physics course', 'maths course', 'class 11', 'class 12',
  '11th course', '12th course', 'dropper course', '11 course',
  '12 course', 'dropper batch', 'crash course', 'rank booster'
].some(k => lower.includes(k));

// Everything else — AI handles (general queries, fees, doubts etc.)
const isKeyword = isStart || isAllCourses || isBook || isTest;

// ─── MOBILE DETECTION ─────────────────────────────────────
const mobileMatch = text.match(/[6-9]\d{9}/);
const detectedMobile = mobileMatch ? mobileMatch[0] : '';

// ─── CLASS DETECTION ──────────────────────────────────────
let currentClass = '';
if      (lower.includes('11th') || lower.includes('class 11') || lower.includes('11 th')) currentClass = '11th';
else if (lower.includes('12th') || lower.includes('class 12') || lower.includes('12 th')) currentClass = '12th';
else if (lower.includes('dropper') || lower.includes('drop') || lower.includes('13th'))   currentClass = 'Dropper';

// ─── JEE YEAR DETECTION ───────────────────────────────────
let jeeYear = '';
if      (lower.includes('2026')) jeeYear = 'JEE 2026';
else if (lower.includes('2027')) jeeYear = 'JEE 2027';
else if (lower.includes('2028')) jeeYear = 'JEE 2028';
else if (lower.includes('dropper'))  jeeYear = 'Dropper';

// ─── INTEREST DETECTION ───────────────────────────────────
let interestedIn = 'General Query';
if      (['fees','fee','price','payment','pay','cost','charges','kitne','kitna','how much'].some(k => lower.includes(k))) interestedIn = 'Fees / Payment';
else if (['admission','enroll','join','batch','seat','kab se','lena hai'].some(k => lower.includes(k)))                   interestedIn = 'Admission / Enrollment';
else if (['book','notes','material','pdf','kota module','pyq'].some(k => lower.includes(k)))                              interestedIn = 'Books / Notes';
else if (isCourseQuery)                                                                                                    interestedIn = 'Course Info';
else if (['test','mock','series','practice','quiz'].some(k => lower.includes(k)))                                         interestedIn = 'Test Series';
else if (['doubt','question','problem','solve','explain'].some(k => lower.includes(k)))                                   interestedIn = 'Academic Doubt';
else if (['discount','offer','coupon','scholarship'].some(k => lower.includes(k)))                                        interestedIn = 'Discount / Offer';

return [{ json: {
  userId, chatId, fullName, firstName, username,
  text, lower,
  dateTime,
  isStart, isAllCourses, isBook, isTest, isCourseQuery, isKeyword,
  currentClass, jeeYear, interestedIn,
  detectedMobile
}}];

// ═══════════════════════════════════════════════════════════
// NODE 03 — MERGE SHEET DATA + CALCULATE LEAD SCORE
// ═══════════════════════════════════════════════════════════
const row = $input.first()?.json || {};
const d   = $('01 | Extract Message Data2').first().json;

const isExisting = !row.error &&
                   String(row['Platform User ID'] || '').trim() !== '';

const onboardingStep = isExisting ? (row['Lead Status'] || 'done') : 'new';
const savedMobile    = row['Mobile Number'] || '';
const prevCount      = parseInt(row['Interaction Count'] || '0');
const newCount       = prevCount + 1;

const resolvedClass   = d.currentClass || row['Current Class']   || '';
const resolvedJeeYear = d.jeeYear      || row['JEE Target Year'] || '';

// ─── POINTS-BASED LEAD SCORING ───────────────────────────
const lower = d.lower;
let scoreGained = 0;

// +4 asked about fees / price / payment
if (['fees','fee','kitne','kitna','price','pricing','cost','charges',
     'how much','kitni','payment','pay'].some(k => lower.includes(k))) scoreGained += 4;

// +3 asked about joining / admission
if (['admission','enroll','enrolment','join karna','join krna',
     'lena hai','leni hai','kab se','batch kab','seat',
     'last date','kab start'].some(k => lower.includes(k))) scoreGained += 3;

// +2 asked comparison / worth-it questions  
if (['worth','worth it','kaisa hai','good hai','better hai',
     'recommend','guarantee','result kaisa','sahi hai',
     'achha hai','best hai'].some(k => lower.includes(k))) scoreGained += 2;

// +2 repeat visitor — 3 or more interactions
if (newCount >= 3) scoreGained += 2;

// +1 shared class or JEE year
if (d.currentClass || d.jeeYear) scoreGained += 1;

// +1 asked about schedule / content details
if (['syllabus','kitne ghante','recorded','live','schedule',
     'timetable','demo','trial','kitne chapter',
     'topic','content'].some(k => lower.includes(k))) scoreGained += 1;

// +1 asked about discount or scholarship
if (['discount','offer','coupon','scholarship',
     'concession','free'].some(k => lower.includes(k))) scoreGained += 1;

// Accumulate — never reset
const prevScore  = parseInt(row['Lead Score'] || '0');
const totalScore = prevScore + scoreGained;

let leadPriority = 'Cold';
if      (totalScore >= 4) leadPriority = 'Hot';
else if (totalScore >= 1) leadPriority = 'Warm';

// Never downgrade
const priorityRank     = { Hot: 3, Warm: 2, Cold: 1 };
const existingPriority = row['Lead Priority'] || 'Cold';
const resolvedPriority = (priorityRank[leadPriority] || 1) >= (priorityRank[existingPriority] || 1)
  ? leadPriority : existingPriority;

return [{ json: {
  ...d,
  isExisting,
  onboardingStep,
  savedMobile,
  newCount,
  resolvedClass,
  resolvedJeeYear,
  resolvedPriority,
  totalScore,
  existingRow: isExisting ? row : null
}}];

const d = $input.first().json;
const text = d.text || '';
const mobileMatch = text.match(/[6-9]\d{9}/);
const mobile = mobileMatch ? mobileMatch[0] : '';
return [{ json: { ...d, collectedMobile: mobile, isValidMobile: mobile.length === 10 } }];

